package br.com.puck.finance;

import br.com.puck.finance.Models.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;import org.springframework.web.bind.annotation.*;import org.springframework.stereotype.*;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;import java.io.*;import org.apache.pdfbox.pdmodel.*;import org.apache.pdfbox.pdmodel.font.*;import org.apache.poi.xssf.streaming.SXSSFWorkbook;import org.apache.poi.ss.usermodel.*;

@RestController @RequestMapping("/api/transactions") class TransactionController {
 private final TransactionService service; TransactionController(TransactionService s){service=s;}
 @PostMapping ResponseEntity<?> create(@Valid @RequestBody TxRequest r){return ResponseEntity.status(201).body(service.create(r));}
 @GetMapping Object list(@RequestParam(required=false)String type,@RequestParam(required=false)String category,@RequestParam(required=false)String description,@RequestParam(required=false)LocalDate startDate,@RequestParam(required=false)LocalDate endDate,@RequestParam(required=false)BigDecimal minAmount,@RequestParam(required=false)BigDecimal maxAmount,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="date,desc")String sort){return service.list(filters(type,category,description,startDate,endDate,minAmount,maxAmount),page,size,sort);}
 @GetMapping("/summary") Object summary(@RequestParam(required=false)String type,@RequestParam(required=false)String category,@RequestParam(required=false)String description,@RequestParam(required=false)LocalDate startDate,@RequestParam(required=false)LocalDate endDate,@RequestParam(required=false)BigDecimal minAmount,@RequestParam(required=false)BigDecimal maxAmount){return service.summary(filters(type,category,description,startDate,endDate,minAmount,maxAmount));}
 @GetMapping("/export.pdf") ResponseEntity<StreamingResponseBody> pdf(@RequestParam(required=false)String type,@RequestParam(required=false)String category,@RequestParam(required=false)String description,@RequestParam(required=false)LocalDate startDate,@RequestParam(required=false)LocalDate endDate,@RequestParam(required=false)BigDecimal minAmount,@RequestParam(required=false)BigDecimal maxAmount){return file(service.export(filters(type,category,description,startDate,endDate,minAmount,maxAmount),false),"application/pdf","movimentacoes.pdf");}
 @GetMapping("/export.xlsx") ResponseEntity<StreamingResponseBody> xlsx(@RequestParam(required=false)String type,@RequestParam(required=false)String category,@RequestParam(required=false)String description,@RequestParam(required=false)LocalDate startDate,@RequestParam(required=false)LocalDate endDate,@RequestParam(required=false)BigDecimal minAmount,@RequestParam(required=false)BigDecimal maxAmount){return file(service.export(filters(type,category,description,startDate,endDate,minAmount,maxAmount),true),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","movimentacoes.xlsx");}
 @GetMapping("/{id}") Object one(@PathVariable UUID id){return service.one(id);}@PutMapping("/{id}") Object update(@PathVariable UUID id,@Valid @RequestBody TxRequest r){return service.update(id,r);}@DeleteMapping("/{id}") ResponseEntity<Void> delete(@PathVariable UUID id){service.delete(id);return ResponseEntity.noContent().build();}
 private Map<String,Object> filters(String t,String c,String d,LocalDate s,LocalDate e,BigDecimal min,BigDecimal max){return Map.ofEntries(Map.entry("type",nil(t)),Map.entry("category",nil(c)),Map.entry("description",nil(d)),Map.entry("startDate",s==null?"":s),Map.entry("endDate",e==null?"":e),Map.entry("minAmount",min==null?"":min),Map.entry("maxAmount",max==null?"":max));}private Object nil(String s){return s==null?"":s;}
 private ResponseEntity<StreamingResponseBody> file(StreamingResponseBody b,String type,String name){return ResponseEntity.ok().header(HttpHeaders.CONTENT_TYPE,type).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+name+"\"").body(b);}
}
record TxRequest(@NotBlank @Size(max=7) String type,@NotBlank @Size(max=255)String description,@NotBlank @Size(max=80)String category,@NotNull @DecimalMin(value="0.01") @Digits(integer=14,fraction=2)BigDecimal amount,@NotNull LocalDate date){}
@Service class TransactionService {
 private final Entries entries;private final Identity identity;TransactionService(Entries e,Identity i){entries=e;identity=i;}
 record TxDto(String id,String type,String description,String category,String amount,String date,String createdAt,String updatedAt){}record PageDto(List<TxDto> content,long totalElements,int page,int size,int totalPages){}record Summary(String income,String expense,String balance,long count){}
 private UUID uid(){UUID id=identity.get();if(id==null)throw new ApiError(HttpStatus.UNAUTHORIZED,"Autenticação necessária.");return id;}
 private Entry owner(UUID id){return entries.owned(uid(),id).orElseThrow(()->new ApiError(HttpStatus.NOT_FOUND,"Movimentação não encontrada."));}
 @Transactional TxDto create(TxRequest r){validate(r);return dto(entries.save(new Entry(uid(),r.type(),AuthService.trim(r.description()),AuthService.trim(r.category()),r.amount(),r.date())));}
 @Transactional TxDto update(UUID id,TxRequest r){validate(r);Entry e=owner(id);e.type=r.type();e.description=AuthService.trim(r.description());e.category=AuthService.trim(r.category());e.amount=r.amount();e.date=r.date();e.updatedAt=OffsetDateTime.now(ZoneOffset.UTC);return dto(entries.save(e));}
 @Transactional void delete(UUID id){entries.delete(owner(id));}
 TxDto one(UUID id){return dto(owner(id));}
 private void validate(TxRequest r){if(!Set.of("INCOME","EXPENSE").contains(r.type()))throw new ApiError(HttpStatus.BAD_REQUEST,"Tipo deve ser INCOME ou EXPENSE.");if(r.amount().signum()<=0||r.amount().scale()>2||r.amount().precision()-r.amount().scale()>14)throw new ApiError(HttpStatus.BAD_REQUEST,"Valor deve ser positivo e ter até 14 inteiros e 2 casas decimais.");if(AuthService.trim(r.description()).isEmpty()||AuthService.trim(r.category()).isEmpty())throw new ApiError(HttpStatus.BAD_REQUEST,"Descrição e categoria são obrigatórias.");}
 private record Criteria(String type,String category,String description,LocalDate start,LocalDate end,BigDecimal min,BigDecimal max,org.springframework.data.domain.Sort sort){}
 private Criteria criteria(Map<String,Object> f,String sort){String order=sort==null?"date,desc":sort;String[] p=order.split(",");if(p.length!=2||!Set.of("date","amount").contains(p[0])||!Set.of("asc","desc").contains(p[1]))throw new ApiError(HttpStatus.BAD_REQUEST,"Ordenação inválida.");var dir=p[1].equals("asc")?org.springframework.data.domain.Sort.Direction.ASC:org.springframework.data.domain.Sort.Direction.DESC;var ordering=org.springframework.data.domain.Sort.by(dir,p[0].equals("date")?"date":"amount").and(org.springframework.data.domain.Sort.by("id"));LocalDate start=val(f,"startDate",LocalDate.class),end=val(f,"endDate",LocalDate.class);BigDecimal min=val(f,"minAmount",BigDecimal.class),max=val(f,"maxAmount",BigDecimal.class);if(start!=null&&end!=null&&start.isAfter(end)||min!=null&&max!=null&&min.compareTo(max)>0)throw new ApiError(HttpStatus.BAD_REQUEST,"Intervalo de filtro invertido.");String type=blank(val(f,"type",String.class));if(type!=null&&!Set.of("INCOME","EXPENSE").contains(type))throw new ApiError(HttpStatus.BAD_REQUEST,"Tipo inválido.");String description=blank(val(f,"description",String.class));description=description==null?"":description.replace("!","!!").replace("%","!%").replace("_","!_");return new Criteria(type,blank(val(f,"category",String.class)),description,start,end,min,max,ordering);}
 private org.springframework.data.domain.Page<Entry> selectedPage(Criteria c,int page,int size){return entries.filtered(uid(),c.type(),c.category(),c.description(),c.start(),c.end(),c.min(),c.max(),org.springframework.data.domain.PageRequest.of(page,size,c.sort()));}
 @SuppressWarnings("unchecked") private <T>T val(Map<String,Object> f,String k,Class<T> c){Object v=f.get(k);if(v==null||v.toString().isBlank())return null;return c.cast(v);}private String blank(String s){return s==null||s.isBlank()?null:s.trim();}
 Object list(Map<String,Object> f,int page,int size,String sort){if(page<0||size<1||size>100)throw new ApiError(HttpStatus.BAD_REQUEST,"page deve ser >= 0 e size entre 1 e 100.");Criteria c=criteria(f,sort);var result=selectedPage(c,page,size);return new PageDto(result.getContent().stream().map(this::dto).toList(),result.getTotalElements(),page,size,result.getTotalPages());}
 Summary summary(Map<String,Object> f){Criteria c=criteria(f,"date,desc");BigDecimal in=BigDecimal.ZERO,out=BigDecimal.ZERO;long count=0;for(int page=0;;page++){var result=selectedPage(c,page,500);for(Entry e:result.getContent()){if(e.type.equals("INCOME"))in=in.add(e.amount);else out=out.add(e.amount);count++;}if(!result.hasNext())break;}return new Summary(in.toPlainString(),out.toPlainString(),in.subtract(out).toPlainString(),count);}
 private static final java.util.concurrent.Semaphore EXPORT_SLOTS=new java.util.concurrent.Semaphore(2);
 org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody export(Map<String,Object> f,boolean excel){if(!EXPORT_SLOTS.tryAcquire())throw new ApiError(HttpStatus.TOO_MANY_REQUESTS,"Há exportações em andamento. Tente novamente.");UUID owner;Criteria c;try{owner=uid();c=criteria(f,"date,desc");}catch(RuntimeException e){EXPORT_SLOTS.release();throw e;}return output->{try{if(excel)writeXlsx(owner,c,output);else writePdf(owner,c,output);}finally{EXPORT_SLOTS.release();}};}
 private org.springframework.data.domain.Page<Entry> selectedPage(UUID owner,Criteria c,int page,int size){return entries.filtered(owner,c.type(),c.category(),c.description(),c.start(),c.end(),c.min(),c.max(),org.springframework.data.domain.PageRequest.of(page,size,c.sort()));}
 private void writeXlsx(UUID owner,Criteria c,OutputStream output)throws IOException{SXSSFWorkbook w=new SXSSFWorkbook(100);try{w.setCompressTempFiles(true);Sheet sheet=w.createSheet("Movimentações");String[] h={"Data","Tipo","Descrição","Categoria","Valor"};Row head=sheet.createRow(0);for(int i=0;i<h.length;i++)head.createCell(i).setCellValue(h[i]);int row=1;BigDecimal in=BigDecimal.ZERO,out=BigDecimal.ZERO;for(int page=0;;page++){var result=selectedPage(owner,c,page,500);for(Entry e:result.getContent()){Row r=sheet.createRow(row++);r.createCell(0).setCellValue(e.date.toString());r.createCell(1).setCellValue(e.type.equals("INCOME")?"Entrada":"Saída");r.createCell(2).setCellValue(e.description);r.createCell(3).setCellValue(e.category);r.createCell(4).setCellValue(e.amount.toPlainString());if(e.type.equals("INCOME"))in=in.add(e.amount);else out=out.add(e.amount);}if(!result.hasNext())break;}Row income=sheet.createRow(row++);income.createCell(3).setCellValue("Total de entradas");income.createCell(4).setCellValue(in.toPlainString());Row expense=sheet.createRow(row++);expense.createCell(3).setCellValue("Total de saídas");expense.createCell(4).setCellValue(out.toPlainString());Row total=sheet.createRow(row);total.createCell(3).setCellValue("Saldo");total.createCell(4).setCellValue(in.subtract(out).toPlainString());for(int i=0;i<h.length;i++)sheet.setColumnWidth(i,i==2?9000:5000);w.write(output);}finally{try{w.dispose();}finally{w.close();}}}
 private void writePdf(UUID owner,Criteria c,OutputStream output)throws IOException{try(PDDocument d=new PDDocument(org.apache.pdfbox.io.IOUtils.createTempFileOnlyStreamCache())){List<String> lines=new ArrayList<>(45);lines.add("Movimentacoes financeiras");BigDecimal in=BigDecimal.ZERO,out=BigDecimal.ZERO;for(int page=0;;page++){var result=selectedPage(owner,c,page,500);for(Entry e:result.getContent()){String description="Descricao: "+e.description;List<String> record=new ArrayList<>();record.add(e.date+" | "+(e.type.equals("INCOME")?"Entrada":"Saida")+" | "+e.category+" | "+e.amount.toPlainString());for(int offset=0;offset<description.length();offset+=92)record.add(description.substring(offset,Math.min(offset+92,description.length())));for(String line:record){lines.add(line);if(lines.size()==45){addPdfPage(d,lines);lines.clear();}}if(e.type.equals("INCOME"))in=in.add(e.amount);else out=out.add(e.amount);}if(!result.hasNext())break;}lines.add("Total de entradas: "+in.toPlainString());lines.add("Total de saidas: "+out.toPlainString());lines.add("Saldo: "+in.subtract(out).toPlainString());if(!lines.isEmpty())addPdfPage(d,lines);d.save(output);}}
 private void addPdfPage(PDDocument d,List<String> lines)throws IOException{PDPage pg=new PDPage();d.addPage(pg);try(PDPageContentStream cs=new PDPageContentStream(d,pg)){cs.beginText();cs.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA),9);cs.newLineAtOffset(40,770);for(String line:lines){cs.newLineAtOffset(0,-14);String printable=java.text.Normalizer.normalize(line,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").replaceAll("[^\\x20-\\x7E]","?");cs.showText(printable);}cs.endText();}}
 private TxDto dto(Entry e){return new TxDto(e.id.toString(),e.type,e.description,e.category,e.amount.toPlainString(),e.date.toString(),e.createdAt.toString(),e.updatedAt.toString());}
}
